import React, {useCallback,useEffect,useState} from "react";
import type {FormEvent,ReactNode} from "react";
import {Inbox,ListChecks,MessageSquare,Settings,Search,RefreshCw,Plus,Mail,AlertCircle,Check,LogOut,Lock,Send,Trash2,Flag,X,Paperclip,ShieldCheck,CalendarClock,CircleDashed,ChevronRight,FileText,ExternalLink,Clock,Link2,Download} from "lucide-react";
import {api} from "./api";

type View="Inbox"|"Follow-ups"|"AI Assistant"|"Accounts & Settings";
const nav:{name:View;icon:typeof Inbox}[]=[
 {name:"Inbox",icon:Inbox},{name:"Follow-ups",icon:ListChecks},{name:"AI Assistant",icon:MessageSquare},{name:"Accounts & Settings",icon:Settings}
];
function Empty({icon:Icon=Mail,title,detail,action}:{icon?:typeof Mail;title:string;detail:string;action?:ReactNode}){
 return <div className="empty"><Icon size={28}/><strong>{title}</strong><span>{detail}</span>{action}</div>;
}
function formatBytes(value:number){if(!Number.isFinite(value)||value<0)return "Unknown size";if(value<1024)return value+" B";if(value<1024*1024)return (value/1024).toFixed(1)+" KB";return (value/1024/1024).toFixed(1)+" MB"}
function toLocalDateTime(value?:string|null){
 if(!value)return "";
 const date=new Date(value);
 if(Number.isNaN(date.getTime()))return "";
 const pad=(n:number)=>String(n).padStart(2,"0");
 return `${date.getFullYear()}-${pad(date.getMonth()+1)}-${pad(date.getDate())}T${pad(date.getHours())}:${pad(date.getMinutes())}`;
}
function Login({onLogin}:{onLogin:(email:string,password:string)=>Promise<void>}){
 const [email,setEmail]=useState("");const [password,setPassword]=useState("");const [error,setError]=useState("");const [busy,setBusy]=useState(false);
 return <div className="login-page"><form className="login-card" onSubmit={async e=>{e.preventDefault();setBusy(true);setError("");try{await onLogin(email,password)}catch(err){setError(err instanceof Error?err.message:"Sign-in failed")}finally{setBusy(false)}}}>
  <div className="mark big">M</div><h1>Email Assistant</h1><p>Your private email workspace</p>
  <label>Email address</label><input type="email" autoComplete="username" value={email} onChange={e=>setEmail(e.target.value)} required/>
  <label>Password</label><input type="password" autoComplete="current-password" value={password} onChange={e=>setPassword(e.target.value)} required/>
  <button className="button primary full" disabled={busy}>{busy?"Signing in…":"Sign in"}</button>
  {error&&<div className="error">{error}</div>}<small className="secure-caption"><Lock size={13}/> Private single-user access</small>
 </form></div>;
}
export default function App(){
 const [user,setUser]=useState<any>(null),[view,setView]=useState<View>("Inbox");
 const [messages,setMessages]=useState<any[]>([]),[accounts,setAccounts]=useState<any[]>([]),[followups,setFollowups]=useState<any[]>([]),[tasks,setTasks]=useState<any[]>([]),[syncJobs,setSyncJobs]=useState<any[]>([]),[settingsData,setSettingsData]=useState<any>({sync_times:["08:00","12:00","17:00"],timezone:"Asia/Kolkata"}),[syncTimesText,setSyncTimesText]=useState("08:00, 12:00, 17:00");
 const [selected,setSelected]=useState<any>(null),[search,setSearch]=useState(""),[notice,setNotice]=useState(""),[busy,setBusy]=useState(false);
 const [showCompose,setShowCompose]=useState(false),[composeBusy,setComposeBusy]=useState(false),[outboundDraft,setOutboundDraft]=useState<any>(null),[savedOutboundDrafts,setSavedOutboundDrafts]=useState<any[]>([]);
 const [outboundFromId,setOutboundFromId]=useState(""),[outboundTo,setOutboundTo]=useState(""),[outboundCc,setOutboundCc]=useState(""),[outboundBcc,setOutboundBcc]=useState(""),[outboundSubject,setOutboundSubject]=useState(""),[outboundBody,setOutboundBody]=useState("");
 const [showAccount,setShowAccount]=useState(false),[provider,setProvider]=useState("icloud"),[newEmail,setNewEmail]=useState(""),[appPassword,setAppPassword]=useState("");
 const [taskTitle,setTaskTitle]=useState(""),[taskText,setTaskText]=useState(""),[taskPriority,setTaskPriority]=useState("normal"),[deadline,setDeadline]=useState(""),[deadlineType,setDeadlineType]=useState("target");
 const [conversations,setConversations]=useState<any[]>([]),[conversation,setConversation]=useState<any>(null),[chatInput,setChatInput]=useState("");
 const [draft,setDraft]=useState<any>(null),[showOriginal,setShowOriginal]=useState(false);
 const [fullThread,setFullThread]=useState<any[]>([]),[fullThreadStatus,setFullThreadStatus]=useState<any>(null),[showFullThread,setShowFullThread]=useState(false),[fullThreadBusy,setFullThreadBusy]=useState(false);
 const [forwardDraft,setForwardDraft]=useState<any>(null),[forwardBusy,setForwardBusy]=useState(false);
 const [threadLink,setThreadLink]=useState<any>(null),[showThreadLinker,setShowThreadLinker]=useState(false),[linkConversationId,setLinkConversationId]=useState(""),[linkAutoUpdate,setLinkAutoUpdate]=useState(true),[linkBusy,setLinkBusy]=useState(false);
 const [attachments,setAttachments]=useState<any[]>([]),[showAttachments,setShowAttachments]=useState(false),[attachmentBusy,setAttachmentBusy]=useState(false),[previewAttachment,setPreviewAttachment]=useState<any>(null);
 const [appleDevices,setAppleDevices]=useState<any[]>([]),[appleCommands,setAppleCommands]=useState<any[]>([]);
 const [appleDeviceName,setAppleDeviceName]=useState("Mehul MacBook"),[appleEnrollment,setAppleEnrollment]=useState<any>(null),[appleBusy,setAppleBusy]=useState(false);
 const [showAppleCommand,setShowAppleCommand]=useState(false),[appleCommandKind,setAppleCommandKind]=useState<"note"|"reminder">("reminder"),[appleCommandTitle,setAppleCommandTitle]=useState(""),[appleCommandBody,setAppleCommandBody]=useState(""),[appleCommandDue,setAppleCommandDue]=useState(""),[appleCommandDeviceId,setAppleCommandDeviceId]=useState("");
 const [followupFilter,setFollowupFilter]=useState<"all"|"action_required"|"awaiting_response">("all");
 const [editingFollowup,setEditingFollowup]=useState<any>(null),[snoozingFollowup,setSnoozingFollowup]=useState<any>(null),[snoozeUntil,setSnoozeUntil]=useState("");
 const refresh=useCallback(async()=>{
  setBusy(true);
  try{const [m,a,f,t,c,s,j,devices,commands]=await Promise.all([api.messages(search),api.accounts(),api.followups(),api.tasks(),api.conversations(),api.settings(),api.syncJobs(),api.appleDevices(),api.appleCommands()]);
   setMessages(m);setAccounts(a);setFollowups(f);setTasks(t);setSyncJobs(j);setConversations(c);setSettingsData(s);setSyncTimesText(s.sync_times.join(", "));setAppleDevices(devices);setAppleCommands(commands);
  }catch(err){setNotice(err instanceof Error?err.message:"Refresh failed")}finally{setBusy(false)}
 },[search]);
 useEffect(()=>{api.me().then(setUser).catch(()=>setUser(false))},[]);
 useEffect(()=>{if(user)refresh()},[user,refresh]);
 useEffect(()=>{if(!selected){setThreadLink(null);setAttachments([]);setShowAttachments(false);setPreviewAttachment(null);setFullThread([]);setFullThreadStatus(null);setShowFullThread(false);return;}let current=true;setThreadLink(null);setAttachments([]);setShowAttachments(false);setPreviewAttachment(null);setShowThreadLinker(false);setFullThread([]);setFullThreadStatus(null);setShowFullThread(false);api.emailThreadLink(selected.id).then(link=>{if(current)setThreadLink(link)}).catch(err=>{if(current)setNotice(err instanceof Error?err.message:"Could not load conversation link")});return()=>{current=false}},[selected?.id]);
 const login=async(email:string,password:string)=>setUser(await api.login(email,password));
 const openMessage=async(m:any,revealOriginal=false)=>{try{const full=await api.message(m.id);await api.markRead(m.id);full.is_read=true;setSelected(full);setDraft(null);setForwardDraft(null);setShowOriginal(revealOriginal);setMessages(rows=>rows.map(x=>x.id===m.id?{...x,is_read:true}:x));return true}catch(err){setNotice(String(err));return false}};
 const prepareReplyFor=async(m:any)=>{if(!await openMessage(m))return;try{setForwardDraft(null);setDraft(await api.createDraft(m.id));setNotice("Reply-all draft created and linked to the original account.")}catch(err){setNotice(err instanceof Error?err.message:String(err))}};
 const setMessageReadState=async(m:any,is_read:boolean)=>{try{await api.setReadState(m.id,is_read);setMessages(rows=>rows.map(x=>x.id===m.id?{...x,is_read}:x));setSelected((current:any)=>current?.id===m.id?{...current,is_read}:current);setNotice(is_read?"Email marked as read in the source mailbox.":"Email marked as unread in the source mailbox.")}catch(err){setNotice(err instanceof Error?err.message:String(err))}};
 const deleteMessageFromCard=async(m:any)=>{if(!window.confirm("Move this email to the source account’s Trash?"))return;try{await api.trash(m.id);setMessages(rows=>rows.filter(x=>x.id!==m.id));if(selected?.id===m.id)setSelected(null);setNotice("Email moved to the source provider’s Trash.")}catch(err){setNotice(err instanceof Error?err.message:String(err))}};
 const blockSenderFromCard=async(m:any)=>{if(!window.confirm("Hide future emails from this sender in this app only? This does not block the sender at Apple or Google."))return;try{const result=await api.block(m.id);if(selected?.id===m.id)setSelected(null);setNotice("Blocked "+result.blocked+" in this app only; the provider has not been changed.");await refresh()}catch(err){setNotice(err instanceof Error?err.message:String(err))}};
 const showAIUnavailable=(m:any,action:string)=>{setNotice(action+" is not active yet for “"+(m.subject||"this email")+"”. The ChatGPT integration is awaiting commercial approval. No summary or answer was generated, and no paid API or credits fallback is enabled.")};
 const loadFullThread=async()=>{if(!selected)return;const messageId=selected.id;setFullThreadBusy(true);try{const result=await api.thread(messageId);if(selected?.id!==messageId)return;setFullThread(result.messages||[]);setFullThreadStatus(result);setShowFullThread(true);if(!result.provider_scan_complete){const reasons=(result.partial_reasons||[]).join(" ");setNotice("The provider returned a thread, but it may be incomplete. "+(reasons||"Some message history could not be verified."))}else{setNotice("Retrieved "+result.message_count+" messages from the source provider. Thread retrieval did not change read status.")}}catch(err){setNotice(err instanceof Error?err.message:String(err))}finally{setFullThreadBusy(false)}};
 const sync=async()=>{try{const r=await api.sync();setNotice(r.queued?String(r.queued)+" mailbox sync job(s) queued.":"No connected email accounts to sync.");await refresh()}catch(err){setNotice(String(err))}};
 const connect=async(e:FormEvent)=>{e.preventDefault();if(provider==="gmail"){window.location.href="/api/oauth/gmail/start";return;}try{await api.addAccount(newEmail,appPassword);setShowAccount(false);setNewEmail("");setAppPassword("");setNotice("iCloud account saved. Initial sync is queued.");await refresh()}catch(err){setNotice(String(err))}};
 const addTask=async(e:FormEvent)=>{e.preventDefault();try{await api.addTask({title:taskTitle,instructions:taskText,priority:taskPriority,deadline_type:deadline?deadlineType:null,deadline_at:deadline?new Date(deadline).toISOString():null});setTaskTitle("");setTaskText("");setDeadline("");setNotice("Task saved. Execution remains blocked until an approved commercial Sign in with ChatGPT integration is available.");await refresh()}catch(err){setNotice(String(err))}};
 const saveSchedule=async(e:FormEvent)=>{e.preventDefault();try{const updated=await api.updateSettings({sync_times:syncTimesText.split(",").map((v:string)=>v.trim()).filter(Boolean),timezone:settingsData.timezone});setSettingsData(updated);setSyncTimesText(updated.sync_times.join(", "));setNotice("Mailbox sync schedule saved. No AI review or notifications will run.")}catch(err){setNotice(String(err))}};
 const createConversation=async()=>{try{const c=await api.newConversation("New conversation");setConversation(c);await refresh()}catch(err){setNotice(String(err))}};
 const selectConversation=async(id:number)=>{try{setConversation(await api.conversation(id))}catch(err){setNotice(String(err))}};
 const sendChat=async(e:FormEvent)=>{e.preventDefault();if(!conversation||!chatInput.trim())return;const content=chatInput;setChatInput("");try{await api.sendMessage(conversation.id,content)}catch(err){setNotice(err instanceof Error?err.message:"AI response unavailable")}finally{await selectConversation(conversation.id)}};
 const openFollowupSource=async(id:number)=>{setView("Inbox");await openMessage({id})};
 const openAttachments=async()=>{if(!selected)return;if(showAttachments){setShowAttachments(false);setPreviewAttachment(null);return;}setAttachmentBusy(true);try{const result=await api.attachments(selected.id);setAttachments(result.attachments||[]);setShowAttachments(true);if(!(result.attachments||[]).length)setNotice("No original file attachments were found on this message.")}catch(err){setNotice(err instanceof Error?err.message:String(err))}finally{setAttachmentBusy(false)}};
 const openThreadLinker=()=>{if(!selected)return;setLinkConversationId(String(threadLink?.conversation_id??conversations[0]?.id??""));setLinkAutoUpdate(threadLink?.auto_update??true);setShowThreadLinker(true)};
 const saveThreadLink=async(e:FormEvent)=>{e.preventDefault();if(!selected||!linkConversationId)return;setLinkBusy(true);try{const result=await api.linkEmailThread(selected.id,Number(linkConversationId),linkAutoUpdate);const link=await api.emailThreadLink(selected.id);setThreadLink(link);setShowThreadLinker(false);setNotice(`Email trail linked. ${result.appended_messages} existing message(s) added; future synced messages will ${result.auto_update?"be appended automatically":"not be appended automatically"}.`);await refresh()}catch(err){setNotice(err instanceof Error?err.message:String(err))}finally{setLinkBusy(false)}};
 const createConversationAndLink=async()=>{if(!selected)return;setLinkBusy(true);try{const created=await api.newConversation(selected.subject?selected.subject.slice(0,480):"Email conversation");const result=await api.linkEmailThread(selected.id,created.id,linkAutoUpdate);setConversation(await api.conversation(created.id));const link=await api.emailThreadLink(selected.id);setThreadLink(link);setShowThreadLinker(false);setNotice(`New Email Assistant conversation created and linked. ${result.appended_messages} existing message(s) added.`);await refresh()}catch(err){setNotice(err instanceof Error?err.message:String(err))}finally{setLinkBusy(false)}};
 const removeThreadLink=async()=>{if(!selected)return;setLinkBusy(true);try{const result=await api.unlinkEmailThread(selected.id);setThreadLink(null);setShowThreadLinker(false);setNotice(result.unlinked?"Email trail unlinked. Existing conversation history is retained; future email updates have stopped.":"This email trail was not linked.");}catch(err){setNotice(err instanceof Error?err.message:String(err))}finally{setLinkBusy(false)}};
 const saveFollowupEdit=async(e:FormEvent)=>{e.preventDefault();if(!editingFollowup)return;try{const {id,due_local,...data}=editingFollowup;data.due_at=due_local?new Date(due_local).toISOString():null;await api.updateFollowup(id,data);setEditingFollowup(null);setNotice("Follow-up updated.");await refresh()}catch(err){setNotice(err instanceof Error?err.message:String(err))}};
 const saveFollowupSnooze=async(e:FormEvent)=>{e.preventDefault();if(!snoozingFollowup||!snoozeUntil)return;const until=new Date(snoozeUntil);if(Number.isNaN(until.getTime())||until.getTime()<=Date.now()){setNotice("Choose a future date and time to snooze this follow-up.");return;}try{await api.snoozeFollowup(snoozingFollowup.id,until.toISOString());setSnoozingFollowup(null);setSnoozeUntil("");setNotice("Follow-up snoozed until "+until.toLocaleString()+".");await refresh()}catch(err){setNotice(err instanceof Error?err.message:String(err))}};
 const createDraft=async()=>{if(!selected)return;try{setForwardDraft(null);setDraft(await api.createDraft(selected.id));setNotice("Reply-all draft created and linked to the original account.")}catch(err){setNotice(String(err))}};
 const createForward=async()=>{if(!selected)return;try{setDraft(null);setForwardDraft(await api.createForwardDraft(selected.id));setNotice("Forward draft created. The From account is locked to the original receiving account.")}catch(err){setNotice(String(err))}};
 const openAppleCommand=(kind:"note"|"reminder")=>{if(!selected)return;setAppleCommandKind(kind);setAppleCommandTitle(kind==="note"?"Email: "+(selected.subject||"Untitled"):"Follow up: "+(selected.subject||"Email"));setAppleCommandBody(kind==="note"?("From: "+selected.sender+"\nSubject: "+selected.subject+"\nReceived: "+(selected.received_at||"")+"\n\n"+(selected.body_text||"")):"");setAppleCommandDue("");setAppleCommandDeviceId("");setShowAppleCommand(true)};
 const queueAppleCommand=async(e:FormEvent)=>{e.preventDefault();if(!appleCommandTitle.trim())return;if(appleCommandKind==="reminder"&&!appleCommandDue){setNotice("Choose a due date and time for the Reminder.");return;}setAppleBusy(true);try{const result=await api.queueAppleCommand({command_type:appleCommandKind,title:appleCommandTitle,body:appleCommandBody,due_at:appleCommandKind==="reminder"?appleCommandDue:null,timezone:"Asia/Kolkata",message_id:selected?.id??null,device_id:appleCommandDeviceId?Number(appleCommandDeviceId):null,idempotency_key:crypto.randomUUID()});setShowAppleCommand(false);setNotice((appleCommandKind==="note"?"Note":"Reminder")+" queued. Status: Pending on Device. It has not been created in Apple until your Shortcut confirms success.");await refresh()}catch(err){setNotice(err instanceof Error?err.message:String(err))}finally{setAppleBusy(false)}};
 const createAppleEnrollment=async()=>{if(!appleDeviceName.trim())return;setAppleBusy(true);try{const result=await api.createAppleEnrollment(appleDeviceName);setAppleEnrollment(result);setNotice("One-time Apple Shortcut enrollment code created. Copy it into the private Shortcut within 15 minutes.")}catch(err){setNotice(err instanceof Error?err.message:String(err))}finally{setAppleBusy(false)}};
 const copyAppleEnrollment=async()=>{if(!appleEnrollment?.enrollment_token)return;try{await navigator.clipboard.writeText(appleEnrollment.enrollment_token);setNotice("Enrollment code copied. It expires at "+new Date(appleEnrollment.expires_at).toLocaleString()+".")}catch{setNotice("Clipboard access is unavailable; select and copy the enrollment code manually.")}};
 const revokeAppleDevice=async(id:number)=>{if(!window.confirm("Revoke this Apple Shortcut device? It will no longer be able to poll or complete commands."))return;try{await api.revokeAppleDevice(id);setNotice("Apple device revoked.");await refresh()}catch(err){setNotice(String(err))}};
 const retryAppleCommand=async(id:number)=>{try{await api.retryAppleCommand(id);setNotice("Apple command returned to Pending on Device.");await refresh()}catch(err){setNotice(String(err))}};
 const cancelAppleCommand=async(id:number)=>{if(!window.confirm("Cancel this queued Apple action? No native item will be created by this command."))return;try{await api.cancelAppleCommand(id);setNotice("Apple command cancelled.");await refresh()}catch(err){setNotice(String(err))}};
 const saveForward=async()=>{if(!forwardDraft)return;setForwardBusy(true);try{const saved=await api.saveForwardDraft(forwardDraft.id,forwardDraft);setForwardDraft(saved);setNotice("Forward draft saved internally.")}catch(err){setNotice(err instanceof Error?err.message:String(err))}finally{setForwardBusy(false)}};
 const sendForward=async()=>{if(!forwardDraft||forwardDraft.status==="sent")return;setForwardBusy(true);try{const saved=await api.saveForwardDraft(forwardDraft.id,forwardDraft);setForwardDraft(saved);const recipients=[...(saved.to||[]),...(saved.cc||[]),...(saved.bcc||[])].join(", ");const prompt="Approve and forward this message?\n\nFrom: "+(saved.from_account||"original account")+"\nTo/CC/BCC: "+recipients+"\nSubject: "+saved.subject+"\nInclude original attachments: "+(saved.include_attachments?"Yes":"No")+"\n\nCover note:\n"+(saved.body||"(none)")+"\n\nThe original email will be included below the cover note. The provider may accept the message; final delivery is not guaranteed.";if(!window.confirm(prompt))return;const result=await api.sendForwardDraft(saved.id,saved.updated_at);setNotice(result.provider_accepted?"The source provider accepted the forwarded email. Delivery is not yet confirmed.":"The provider did not confirm acceptance.");setForwardDraft({...saved,status:"sent"})}catch(err){setNotice(err instanceof Error?err.message:String(err))}finally{setForwardBusy(false)}};
 const openCompose=async()=>{setOutboundDraft(null);setOutboundFromId("");setOutboundTo("");setOutboundCc("");setOutboundBcc("");setOutboundSubject("");setOutboundBody("");setShowCompose(true);try{setSavedOutboundDrafts(await api.outboundDrafts())}catch(err){setNotice(err instanceof Error?err.message:String(err))}};
 const resumeOutboundDraft=(item:any)=>{setOutboundDraft(item);setOutboundFromId(String(item.account_id));setOutboundTo((item.to||[]).join(", "));setOutboundCc((item.cc||[]).join(", "));setOutboundBcc((item.bcc||[]).join(", "));setOutboundSubject(item.subject||"");setOutboundBody(item.body||"")};
 const outboundPayload=()=>({account_id:Number(outboundFromId),to:outboundTo.split(",").map((v:string)=>v.trim()).filter(Boolean),cc:outboundCc.split(",").map((v:string)=>v.trim()).filter(Boolean),bcc:outboundBcc.split(",").map((v:string)=>v.trim()).filter(Boolean),subject:outboundSubject,body:outboundBody});
 const saveOutboundDraft=async()=>{if(!outboundFromId){setNotice("Choose the From account explicitly before saving this email.");return null;}setComposeBusy(true);try{const data=outboundPayload();const saved=outboundDraft?.id?await api.saveOutboundDraft(outboundDraft.id,data):await api.createOutboundDraft(data);setOutboundDraft(saved);setSavedOutboundDrafts(rows=>[saved,...rows.filter((x:any)=>x.id!==saved.id)]);setNotice("New email saved as an internal draft. It has not been sent or added to your provider Drafts.");return saved}catch(err){setNotice(err instanceof Error?err.message:String(err));return null}finally{setComposeBusy(false)}};
 const sendOutboundEmail=async()=>{if(!outboundFromId){setNotice("Choose the From account explicitly before sending.");return;}const data=outboundPayload();if(!(data.to.length+data.cc.length+data.bcc.length)){setNotice("Add at least one recipient.");return;}if(!data.subject.trim()||!data.body.trim()){setNotice("Add a subject and message body before sending.");return;}setComposeBusy(true);try{const saved=outboundDraft?.id?await api.saveOutboundDraft(outboundDraft.id,data):await api.createOutboundDraft(data);setOutboundDraft(saved);const recipients=[...data.to,...data.cc,...data.bcc].join(", ");const prompt="Approve and send this new email?\n\nFrom: "+saved.from_account+"\nTo/CC/BCC: "+recipients+"\nSubject: "+saved.subject+"\n\nMessage:\n"+saved.body+"\n\nThe selected provider may accept the email; final delivery is not guaranteed.";if(!window.confirm(prompt)){setSavedOutboundDrafts(rows=>[saved,...rows.filter((x:any)=>x.id!==saved.id)]);setNotice("Draft saved. No email was sent.");return;}const result=await api.sendOutboundDraft(saved.id,saved.updated_at);setNotice(result.provider_accepted?"The selected provider accepted the new email. Final delivery is not yet confirmed.":"The provider did not confirm acceptance.");setSavedOutboundDrafts(rows=>rows.filter((x:any)=>x.id!==saved.id));setShowCompose(false);setOutboundDraft(null);await refresh()}catch(err){setNotice(err instanceof Error?err.message:String(err))}finally{setComposeBusy(false)}};
 const saveDraft=async()=>{if(!draft)return;try{setDraft(await api.saveDraft(draft.id,draft));setNotice("Internal draft saved.")}catch(err){setNotice(String(err))}};
 const sendDraft=async()=>{if(!draft||draft.status==="sent")return;try{const saved=await api.saveDraft(draft.id,draft);setDraft(saved);const recipients=[...(saved.to||[]),...(saved.cc||[]),...(saved.bcc||[])].join(", ");const prompt="Send the saved version below?\n\nFrom: "+(saved.from_account||"original account")+"\nTo/CC/BCC: "+recipients+"\nSubject: "+saved.subject+"\n\nMessage:\n"+saved.body+"\n\nThe source provider may accept the message; final delivery is not guaranteed.";if(!window.confirm(prompt))return;const result=await api.sendDraft(saved.id,saved.updated_at);setNotice(result.provider_accepted?"The source provider accepted the email. Delivery is not yet confirmed.":"The provider did not confirm acceptance.");setDraft({...saved,status:"sent"});await refresh()}catch(err){setNotice(err instanceof Error?err.message:String(err));}};
 if(user===null)return <div className="splash">Loading private workspace…</div>;
 if(user===false)return <Login onLogin={login}/>;
 const active=tasks.filter(t=>["queued","in_progress"].includes(t.status));
 const waiting=tasks.filter(t=>t.status==="waiting_for_user").length;
 const unread=messages.filter(m=>!m.is_read).length;
 const visibleFollowups=followups.filter((f:any)=>followupFilter==="all"||f.status===followupFilter);
 return <div className="app-shell">
  <aside className="sidebar"><div className="brand"><div className="mark">M</div><div><b>Email Assistant</b><small>Private workspace</small></div></div><div className="nav-label">WORKSPACE</div>
   {nav.map(n=><button key={n.name} className={"nav-item "+(view===n.name?"active":"")} onClick={()=>{setView(n.name);setSelected(null)}}><n.icon size={18}/><span>{n.name}</span>{n.name==="Inbox"&&unread>0&&<em>{unread}</em>}</button>)}
   <div className="sidebar-bottom"><div className="privacy-chip"><ShieldCheck size={16}/> Private account</div><button className="nav-item" onClick={async()=>{await api.logout();setUser(false)}}><LogOut size={17}/> Sign out</button><small>{user.email}</small></div>
  </aside>
  <main className="main-area"><header className="topbar"><div><span className="eyebrow">YOUR WORKSPACE</span><h1>{view}</h1></div><div className="top-actions"><span className="connection-state"><CircleDashed size={14}/> AI integration pending approval</span><button className="icon-button" title="Refresh" onClick={refresh}><RefreshCw size={17}/></button>{view==="Inbox"&&<button className="button secondary" onClick={openCompose}><Plus size={15}/> Compose</button>}<button className="button primary" onClick={sync}><RefreshCw size={15}/> Sync Now</button></div></header>
   {notice&&<div className="notice"><AlertCircle size={16}/><span>{notice}</span><button onClick={()=>setNotice("")} aria-label="Dismiss"><X size={15}/></button></div>}
   {view==="Inbox"&&<section className="inbox-layout"><div className="list-pane"><div className="pane-heading"><div><b>All mail</b><small>{messages.length} messages · {unread} unread</small></div><button className="icon-button" onClick={()=>setShowAccount(true)}><Plus size={18}/></button></div><form className="searchbox" onSubmit={e=>{e.preventDefault();refresh()}}><Search size={16}/><input placeholder="Search sender, subject or content" value={search} onChange={e=>setSearch(e.target.value)}/><button><ChevronRight size={16}/></button></form>
    {busy?<Empty title="Loading inbox" detail="Fetching saved email records…"/>:messages.length===0?<Empty title="Your inbox is ready" detail="Connect an iCloud account to begin." action={<button className="button secondary" onClick={()=>setShowAccount(true)}>Connect account</button>}/>:messages.map(m=><div key={m.id} className={"message-card "+(selected?.id===m.id?"selected":"")}>
     <button type="button" className={"message-row "+(m.is_read?"":"unread")} onClick={()=>openMessage(m)}><div className="row-top"><b>{m.sender}</b><small>{m.received_at?new Date(m.received_at).toLocaleDateString():""}</small></div><strong>{m.subject||"(No subject)"}</strong><p>{m.summary||m.snippet||"No preview available"}</p><div className="row-meta"><span className={"priority "+m.priority}>{m.priority}</span>{m.has_attachments&&<Paperclip size={13}/>}</div></button>
     <div className="message-card-actions">
      <button type="button" className="button secondary compact" onClick={()=>openMessage(m,true)}>View Original</button>
      <button type="button" className="button secondary compact" onClick={()=>prepareReplyFor(m)}>Prepare Reply</button>
      <button type="button" className="button secondary compact" onClick={()=>setMessageReadState(m,!m.is_read)}>{m.is_read?"Mark as Unread":"Mark as Read"}</button>
      <button type="button" className="button secondary compact danger" onClick={()=>deleteMessageFromCard(m)}>Delete</button>
      <button type="button" className="button secondary compact" onClick={()=>blockSenderFromCard(m)}>Block Sender</button>
      <button type="button" className="button secondary compact ai-pending" title="Awaiting approved ChatGPT integration" onClick={()=>showAIUnavailable(m,"Summarise Entire Thread")}>Summarise Entire Thread</button>
      <button type="button" className="button secondary compact ai-pending" title="Awaiting approved ChatGPT integration" onClick={()=>showAIUnavailable(m,"Ask a Question")}>Ask a Question</button>
     </div>
    </div>)}
   </div><div className="detail-pane">{selected?<><div className="detail-head"><div><small>{selected.account_email}</small><h2>{selected.subject||"(No subject)"}</h2><p>{selected.sender} · {selected.received_at?new Date(selected.received_at).toLocaleString():""}</p></div><button className="icon-button" onClick={()=>setSelected(null)}><X size={18}/></button></div>
    <div className="summary-card"><label>THIS EMAIL</label><p>{selected.summary||"No AI summary available yet."}</p></div><div className="summary-card"><label>ENTIRE EMAIL TRAIL</label><p>{selected.thread_summary||"No AI thread summary available yet."}</p></div>
    <div className="inline-actions detail-view-tools"><button className="button secondary" onClick={()=>setShowOriginal(v=>!v)}>{showOriginal?"Hide original email":"Show original email"}</button><button className="button secondary" onClick={loadFullThread} disabled={fullThreadBusy}>{fullThreadBusy?"Retrieving thread…":showFullThread?"Refresh full thread":"View full thread"}</button></div>{showOriginal&&<div className="original"><label>ORIGINAL EMAIL</label><pre>{selected.body_text||"No plain-text body was imported."}</pre></div>}
    {showFullThread&&<div className="full-thread-panel"><div className="full-thread-heading"><div><b>Complete email trail</b><small>{fullThread.length} message(s) · Chronological order · {fullThreadStatus?.account_email||selected.account_email}</small></div><span className={fullThreadStatus?.provider_scan_complete?"thread-complete":"thread-partial"}>{fullThreadStatus?.provider_scan_complete?"Provider scan completed":"Possible gaps"}</span></div><p className="thread-read-note">Messages are retrieved with read-only provider operations. Loading this trail does not mark the other messages as read.</p>{(fullThreadStatus?.partial_reasons||[]).map((reason:string,index:number)=><p className="thread-warning" key={index}>{reason}</p>)}{fullThread.map((item:any)=><article className="thread-message" key={item.id}><div className="thread-message-head"><b>{item.sender||"Unknown sender"}</b><small>{item.received_at?new Date(item.received_at).toLocaleString():"Date unavailable"} · {item.is_read?"Read":"Unread"}</small></div><p className="thread-subject">{item.subject||"(No subject)"}</p><p className="thread-recipients">To / CC: {item.recipients||"Not available"}</p><pre>{item.body_text||"No plain-text body was available for this message."}</pre>{item.has_attachments&&<small className="thread-attachment-note">This message has attachment(s). Select it in the inbox to view or download its original files.</small>}</article>)}</div>}
    {showAttachments&&<div className="attachments-panel"><div className="attachments-heading"><div><b>Original attachments</b><small>Fetched securely from the source mailbox · not permanently stored</small></div><span className="count-pill">{attachments.length} files</span></div>{attachments.length===0?<p className="attachment-empty">No downloadable file attachments were found.</p>:attachments.map((item:any)=><div className="attachment-row" key={item.index}><div className="attachment-icon"><Paperclip size={16}/></div><div className="attachment-info"><b>{item.filename}</b><small>{item.mime_type} · {formatBytes(item.size)}{item.is_inline?" · Inline image":""}</small></div><div className="attachment-buttons">{item.available===false?<span className="attachment-limit">Over 25 MB limit</span>:<>{item.can_preview&&<button className="button secondary compact" onClick={()=>setPreviewAttachment(item)}>View Original</button>}<a className="button secondary compact" href={api.attachmentUrl(selected.id,item.index,false)} download={item.filename}><Download size={13}/> Download</a></>}</div></div>)}</div>}
    {previewAttachment&&<div className="modal-backdrop attachment-backdrop"><div className="attachment-viewer"><div className="attachment-viewer-head"><div><b>{previewAttachment.filename}</b><small>{previewAttachment.mime_type} · {formatBytes(previewAttachment.size)}</small></div><div className="inline-actions"><a className="button secondary compact" href={api.attachmentUrl(selected.id,previewAttachment.index,false)} download={previewAttachment.filename}><Download size={13}/> Download</a><button className="icon-button" onClick={()=>setPreviewAttachment(null)}><X size={17}/></button></div></div>{previewAttachment.mime_type.startsWith("image/")?<div className="attachment-image-stage"><img src={api.attachmentUrl(selected.id,previewAttachment.index,true)} alt={previewAttachment.filename}/></div>:<iframe className="attachment-pdf-frame" src={api.attachmentUrl(selected.id,previewAttachment.index,true)} title={previewAttachment.filename}/>}</div></div>}
    {draft&&<div className="draft-editor"><div className="draft-title"><FileText size={16}/> Internal reply draft <span>{draft.status === "sent" ? "Sent" : "Not sent"}</span></div>
     <label>To (comma-separated)</label><input value={(draft.to||[]).join(", ")} onChange={e=>setDraft({...draft,to:e.target.value.split(",").map((v:string)=>v.trim()).filter(Boolean)})}/>
     <label>CC</label><input value={(draft.cc||[]).join(", ")} onChange={e=>setDraft({...draft,cc:e.target.value.split(",").map((v:string)=>v.trim()).filter(Boolean)})}/>
     <label>BCC</label><input value={(draft.bcc||[]).join(", ")} onChange={e=>setDraft({...draft,bcc:e.target.value.split(",").map((v:string)=>v.trim()).filter(Boolean)})}/>
     <small>From is locked to the account that received this email: {draft.from_account||"original account"}</small>
     <label>Subject</label><input value={draft.subject||""} onChange={e=>setDraft({...draft,subject:e.target.value})}/>
     <label>Message</label><textarea rows={7} value={draft.body||""} onChange={e=>setDraft({...draft,body:e.target.value})}/>
     <div className="inline-actions"><button className="button secondary" onClick={saveDraft}>Save draft</button><button className="button secondary" onClick={sendDraft}>Approve &amp; Send</button></div></div>}
    <div className="detail-actions"><button className="button secondary" onClick={createDraft}>Create Reply</button><button className="button secondary" onClick={openThreadLinker}><Link2 size={15}/>{threadLink?"Manage AI conversation":"Link to AI conversation"}</button><button className="button secondary" onClick={async()=>{if(!selected||!window.confirm("Move this email to the source account’s Trash?"))return;try{await api.trash(selected.id);setSelected(null);setNotice("Email moved to the provider’s Trash.");await refresh()}catch(err){setNotice(String(err))}}}><Trash2 size={15}/> Move to Trash</button><button className="button secondary" onClick={async()=>{if(!selected||!window.confirm("Hide future messages from this sender in this app? This does not block the sender at Apple or Google."))return;try{const r=await api.block(selected.id);setNotice("Blocked "+r.blocked+" in this app only.");await refresh()}catch(err){setNotice(String(err))}}}><Flag size={15}/> Block in app</button><button className="button secondary" onClick={createForward}><Send size={15}/> Forward</button><button className="button secondary" onClick={openAttachments} disabled={attachmentBusy}><Paperclip size={15}/>{attachmentBusy?"Loading…":showAttachments?"Hide Attachments":"Attachments"}</button><button className="button secondary" onClick={()=>openAppleCommand("reminder")}><CalendarClock size={15}/> Add Reminder</button><button className="button secondary" onClick={()=>openAppleCommand("note")}><FileText size={15}/> Add Note</button></div>
    {forwardDraft&&<div className="modal-backdrop"><form className="modal forward-modal" onSubmit={e=>{e.preventDefault();saveForward()}}>
     <div className="section-head"><h2>Forward email</h2><button type="button" className="icon-button" onClick={()=>setForwardDraft(null)}><X size={17}/></button></div>
     <p className="modal-description">This creates a separate forward, not a reply. The original email details and selected attachments are included below your cover note. The source From account is locked.</p>
     <label>From (locked to source account)</label><input value={forwardDraft.from_account||selected?.account_email||"Original account"} readOnly/>
     <label>To (comma-separated)</label><input value={(forwardDraft.to||[]).join(", ")} onChange={e=>setForwardDraft({...forwardDraft,to:e.target.value.split(",").map((v:string)=>v.trim()).filter(Boolean)})} placeholder="recipient@example.com"/>
     <label>CC</label><input value={(forwardDraft.cc||[]).join(", ")} onChange={e=>setForwardDraft({...forwardDraft,cc:e.target.value.split(",").map((v:string)=>v.trim()).filter(Boolean)})}/>
     <label>BCC</label><input value={(forwardDraft.bcc||[]).join(", ")} onChange={e=>setForwardDraft({...forwardDraft,bcc:e.target.value.split(",").map((v:string)=>v.trim()).filter(Boolean)})}/>
     <label>Subject</label><input value={forwardDraft.subject||""} onChange={e=>setForwardDraft({...forwardDraft,subject:e.target.value})}/>
     <label>Message / cover note (optional)</label><textarea rows={5} value={forwardDraft.body||""} onChange={e=>setForwardDraft({...forwardDraft,body:e.target.value})} placeholder="Add a note above the forwarded email…"/>
     <label className="inline-check"><input type="checkbox" checked={forwardDraft.include_attachments!==false} onChange={e=>setForwardDraft({...forwardDraft,include_attachments:e.target.checked})}/> Include original attachments (up to 25 MB combined)</label>
     <small className="forward-source-note">Original message: {selected?.subject} · {selected?.sender} · {selected?.received_at?new Date(selected.received_at).toLocaleString():"date unavailable"}</small>
     <div className="inline-actions"><button type="button" className="button secondary" onClick={saveForward} disabled={forwardBusy}>{forwardBusy?"Saving…":"Save draft"}</button><button type="button" className="button primary" onClick={sendForward} disabled={forwardBusy||forwardDraft.status==="sent"}>{forwardBusy?"Working…":forwardDraft.status==="sent"?"Sent":"Approve & Forward"}</button></div>
    </form></div>}
    {showAppleCommand&&<div className="modal-backdrop"><form className="modal apple-command-modal" onSubmit={queueAppleCommand}>
     <div className="section-head"><h2>{appleCommandKind==="note"?"Add Apple Note":"Add Apple Reminder"}</h2><button type="button" className="icon-button" onClick={()=>setShowAppleCommand(false)}><X size={17}/></button></div>
     <p className="modal-description">This queues a secure command for an enrolled Apple Shortcut. The native item is not created until your device runs the Shortcut and confirms success.</p>
     <label>Title</label><input value={appleCommandTitle} onChange={e=>setAppleCommandTitle(e.target.value)} required maxLength={500}/>
     {appleCommandKind==="reminder"&&<><label>Due date and time (Asia/Kolkata)</label><input type="datetime-local" value={appleCommandDue} onChange={e=>setAppleCommandDue(e.target.value)} required/></>}
     <label>{appleCommandKind==="note"?"Note content":"Reminder details (optional)"}</label><textarea rows={appleCommandKind==="note"?9:4} value={appleCommandBody} onChange={e=>setAppleCommandBody(e.target.value)} maxLength={20000} required={appleCommandKind==="note"}/>
     <label>Apple device</label><select value={appleCommandDeviceId} onChange={e=>setAppleCommandDeviceId(e.target.value)}><option value="">Any enrolled device</option>{appleDevices.filter((d:any)=>d.is_active).map((d:any)=><option key={d.id} value={d.id}>{d.name}</option>)}</select>
     {appleDevices.filter((d:any)=>d.is_active).length===0&&<p className="apple-pending-note">No device is enrolled. This command will be saved as Pending on Device until you enrol a Shortcut.</p>}
     <p className="apple-pending-note">Source email: {selected?.subject||"Not linked"} · The email remains unchanged.</p>
     <div className="inline-actions"><button type="button" className="button secondary" onClick={()=>setShowAppleCommand(false)}>Cancel</button><button className="button primary" disabled={appleBusy}>{appleBusy?"Queueing…":"Queue on Apple device"}</button></div>
    </form></div>}
    {showThreadLinker&&<div className="modal-backdrop"><form className="modal" onSubmit={saveThreadLink}>
     <div className="section-head"><h2>{threadLink?"Manage email conversation link":"Link email to a conversation"}</h2><button type="button" className="icon-button" onClick={()=>setShowThreadLinker(false)}><X size={17}/></button></div>
     <p className="modal-description">Add the existing messages in this provider thread to an Email Assistant conversation. Newly synced messages can be appended once automatically. This does not access or change your regular ChatGPT chats.</p>
     {threadLink&&<p className="thread-link-current">Currently linked to <b>{threadLink.conversation_title}</b> · {threadLink.linked_message_count} email(s) already tracked.</p>}
     <label>Destination conversation</label><select value={linkConversationId} onChange={e=>setLinkConversationId(e.target.value)} required><option value="">Select a conversation</option>{conversations.map(c=><option key={c.id} value={c.id}>{c.title}</option>)}</select>
     <label className="inline-check"><input type="checkbox" checked={linkAutoUpdate} onChange={e=>setLinkAutoUpdate(e.target.checked)}/> Append future emails from this thread automatically</label>
     <div className="inline-actions">{!threadLink&&<button type="button" className="button secondary" onClick={createConversationAndLink} disabled={linkBusy}>Create new conversation</button>}<button className="button primary" disabled={linkBusy||!linkConversationId}>{linkBusy?"Saving…":threadLink?"Update link":"Link conversation"}</button></div>
     {threadLink&&<button type="button" className="text-danger" onClick={removeThreadLink} disabled={linkBusy}>Unlink thread (keep conversation history)</button>}
    </form></div>}
   </>:<Empty title="Select an email" detail="Summaries, original content and available actions appear here."/>}</div></section>}
   {view==="Follow-ups"&&<section className="content-card followups-card">
    <div className="section-head"><div><h2>Follow-ups</h2><p>Track commitments and responses linked to your emails.</p></div><span className="count-pill">{followups.length} active</span></div>
    <div className="followup-filters">
     <button className={followupFilter==="all"?"chosen":""} onClick={()=>setFollowupFilter("all")}>All <span>{followups.length}</span></button>
     <button className={followupFilter==="action_required"?"chosen":""} onClick={()=>setFollowupFilter("action_required")}>Action Required <span>{followups.filter((f:any)=>f.status==="action_required").length}</span></button>
     <button className={followupFilter==="awaiting_response"?"chosen":""} onClick={()=>setFollowupFilter("awaiting_response")}>Awaiting Response <span>{followups.filter((f:any)=>f.status==="awaiting_response").length}</span></button>
    </div>
    {visibleFollowups.length===0?<Empty icon={Check} title="No follow-ups in this view" detail="Follow-up records will appear here when they are added. No email is changed when a follow-up is completed or removed."/>:
     <div className="followup-list">{visibleFollowups.map((f:any)=>{
      const overdue=Boolean(f.due_at&&new Date(f.due_at).getTime()<Date.now());
      return <div className="followup-row" key={f.id}>
       <div className="followup-main">
        <div className="followup-title-row"><b>{f.title}</b><span className={"followup-state "+(overdue?"overdue":f.status)}>{overdue?"Overdue":f.status.replaceAll("_"," ")}</span></div>
        {f.description&&<p>{f.description}</p>}
        <small>{f.owner||"Owner not specified"} · {f.due_at?"Due "+new Date(f.due_at).toLocaleString():"No due date"}{f.message_id?" · Linked to an email":""}</small>
       </div>
       <div className="followup-actions">
        {f.message_id&&<button className="button secondary compact" onClick={()=>openFollowupSource(f.message_id)}>Open Email Trail</button>}
        <button className="button secondary compact" onClick={async()=>{try{await api.completeFollowup(f.id);setNotice("Follow-up marked complete.");await refresh()}catch(err){setNotice(String(err))}}}>Mark Complete</button>
        <button className="button secondary compact" onClick={()=>setEditingFollowup({...f,due_local:toLocalDateTime(f.due_at)})}>Edit</button>
        <button className="button secondary compact" onClick={()=>{setSnoozingFollowup(f);const suggested=f.due_at&&new Date(f.due_at).getTime()>Date.now()?f.due_at:new Date(Date.now()+24*60*60*1000).toISOString();setSnoozeUntil(toLocalDateTime(suggested))}}>Snooze</button>
        <button className="followup-remove" onClick={async()=>{if(!window.confirm("Remove this tracking item only? The email and conversation will remain unchanged."))return;try{await api.removeFollowup(f.id);setNotice("Follow-up removed. The email and conversation were retained.");await refresh()}catch(err){setNotice(String(err))}}}>Remove from Follow-ups</button>
       </div>
      </div>
     })}</div>}
    {editingFollowup&&<div className="modal-backdrop"><form className="modal" onSubmit={saveFollowupEdit}>
     <div className="section-head"><h2>Edit follow-up</h2><button type="button" className="icon-button" onClick={()=>setEditingFollowup(null)}><X size={17}/></button></div>
     <label>Task</label><input value={editingFollowup.title||""} onChange={e=>setEditingFollowup({...editingFollowup,title:e.target.value})} required maxLength={500}/>
     <label>Description</label><textarea rows={4} value={editingFollowup.description||""} onChange={e=>setEditingFollowup({...editingFollowup,description:e.target.value})}/>
     <label>Responsible party</label><input value={editingFollowup.owner||""} onChange={e=>setEditingFollowup({...editingFollowup,owner:e.target.value})} maxLength={200}/>
     <label>Due / expected date</label><input type="datetime-local" value={editingFollowup.due_local||""} onChange={e=>setEditingFollowup({...editingFollowup,due_local:e.target.value})}/>
     <label>Tracking status</label><select value={editingFollowup.status||"action_required"} onChange={e=>setEditingFollowup({...editingFollowup,status:e.target.value})}><option value="action_required">Action Required</option><option value="awaiting_response">Awaiting Response</option></select>
     <div className="inline-actions"><button type="button" className="button secondary" onClick={()=>setEditingFollowup(null)}>Cancel</button><button className="button primary">Save changes</button></div>
    </form></div>}
    {snoozingFollowup&&<div className="modal-backdrop"><form className="modal" onSubmit={saveFollowupSnooze}>
     <div className="section-head"><h2>Snooze follow-up</h2><button type="button" className="icon-button" onClick={()=>setSnoozingFollowup(null)}><X size={17}/></button></div>
     <p className="modal-description">Hide this follow-up from active views until the selected review time. Its history and linked email will remain unchanged.</p>
     <label>Remind me to review on</label><input type="datetime-local" value={snoozeUntil} onChange={e=>setSnoozeUntil(e.target.value)} required/>
     <div className="inline-actions"><button type="button" className="button secondary" onClick={()=>setSnoozingFollowup(null)}>Cancel</button><button className="button primary">Save snooze</button></div>
    </form></div>}
   </section>}
   {view==="AI Assistant"&&<section className="assistant-layout"><div className="chat-panel"><div className="section-head"><div><h2>AI Assistant</h2><p>Persistent Email Assistant conversations · separate from ChatGPT history</p></div><button className="button secondary" onClick={createConversation}><Plus size={15}/> New chat</button></div>
    <div className="conversation-strip">{conversations.map(c=><button key={c.id} className={"conversation-pill "+(conversation?.id===c.id?"chosen":"")} onClick={()=>selectConversation(c.id)}>{c.title}</button>)}</div>
    <div className="chat-body">{conversation?.messages?.length?conversation.messages.map((m:any,i:number)=><div className={"bubble "+m.role} key={i}><small>{m.role==="user"?"You":m.role==="assistant"?"Assistant":m.role==="email"?"Email update":"System"}</small><p>{m.content}</p></div>):<Empty icon={MessageSquare} title="What would you like to work on?" detail="Your app-managed conversation history is saved. AI responses remain paused until OpenAI approves a commercial Sign in with ChatGPT integration for this app. The open-source DevKit licence is noncommercial and has not been included. No paid API or credit fallback is enabled."/>}</div>
    <form className="chat-input" onSubmit={sendChat}><input value={chatInput} onChange={e=>setChatInput(e.target.value)} placeholder="Ask your assistant…"/><button className="button primary" disabled={!conversation||!chatInput.trim()}><Send size={16}/></button></form>
   </div><aside className="task-panel"><div className="section-head"><h2>AI tasks</h2><span className="count-pill">{active.length} active · {waiting} waiting · max 3</span></div>
    <form className="task-create" onSubmit={addTask}><input value={taskTitle} onChange={e=>setTaskTitle(e.target.value)} placeholder="Task title" required maxLength={500}/><textarea value={taskText} onChange={e=>setTaskText(e.target.value)} placeholder="Describe what you want done…"/>
     <label>Priority</label><select value={taskPriority} onChange={e=>setTaskPriority(e.target.value)}><option value="urgent">Urgent</option><option value="high">High</option><option value="normal">Normal</option><option value="low">Low</option></select>
     <label>Deadline (optional)</label><input type="datetime-local" value={deadline} onChange={e=>setDeadline(e.target.value)}/>{deadline&&<select value={deadlineType} onChange={e=>setDeadlineType(e.target.value)}><option value="target">Target deadline</option><option value="hard">Hard deadline</option></select>}
     <button className="button primary full"><Plus size={15}/> Add task</button></form>
    {tasks.map(t=><div className="task-card" key={t.id}><div className="row-top"><b>{t.title}</b><span className={"priority "+t.priority}>{t.priority}</span></div><small>{t.status.replaceAll("_"," ")} · {t.deadline_type||"No deadline"}</small><p>{t.blocker}</p><div className="inline-actions"><select aria-label="Task priority" value={t.priority_override_by_user?t.priority:"automatic"} onChange={async e=>{await api.priority(t.id,e.target.value==="automatic"?null:e.target.value);await refresh()}}><option value="automatic">Automatic</option><option value="urgent">Urgent</option><option value="high">High</option><option value="normal">Normal</option><option value="low">Low</option></select><button className="icon-button" title="Cancel task" onClick={async()=>{await api.cancelTask(t.id);await refresh()}}><X size={15}/></button></div></div>)}
   </aside></section>}
   {view==="Accounts & Settings"&&<section className="content-card"><div className="section-head"><div><h2>Email accounts</h2><p>Never use your normal Apple ID password here.</p></div><button className="button primary" onClick={()=>setShowAccount(true)}><Plus size={15}/> Add account</button></div>
    {accounts.length===0?<Empty title="No connected accounts" detail="Connect an iCloud mailbox to begin." action={<button className="button secondary" onClick={()=>setShowAccount(true)}>Connect account</button>}/>:accounts.map(a=><div className="account-row" key={a.id}><div className="account-icon"><Mail size={18}/></div><div><b>{a.email}</b><small>{a.provider.toUpperCase()} · {a.status} · {a.last_sync_at?new Date(a.last_sync_at).toLocaleString():"Never synced"}</small></div><span className="spacer"/><button className="button secondary compact" onClick={async()=>{await api.syncOne(a.id);setNotice("Sync job queued.");await refresh()}}>Sync now</button><button className="button secondary compact" onClick={async()=>{if(confirm("Disconnect account? Imported history remains.")){await api.disconnectAccount(a.id);await refresh()}}}>Disconnect</button></div>)}
    <div className="settings-block"><div className="section-head"><h3>Recent mailbox sync activity</h3><button className="button secondary compact" onClick={refresh}>Refresh status</button></div>{syncJobs.length===0?<p>No mailbox sync jobs yet.</p>:syncJobs.slice(0,8).map(job=>{const account=accounts.find(a=>a.id===job.account_id);return <div className="item-row" key={job.id}><div><b>{account?.email||"Email account"}</b><p>{job.details||"Mailbox sync"}</p><small>{job.created_at?new Date(job.created_at).toLocaleString():""}</small></div><span className="count-pill">{job.status.replaceAll("_"," ")}</span></div>})}</div>
    <div className="settings-block apple-bridge">
     <div className="section-head"><div><h3>Apple Notes &amp; Reminders</h3><p>Native actions run on an enrolled Mac or iPhone Shortcut. Commands stay pending until a device confirms creation.</p></div><span className="count-pill">{appleDevices.filter((d:any)=>d.is_active).length} active devices</span></div>
     <div className="apple-enroll-row"><input aria-label="Apple device name" value={appleDeviceName} onChange={e=>setAppleDeviceName(e.target.value)} placeholder="Device name (e.g. Mehul MacBook)"/><button className="button secondary compact" onClick={createAppleEnrollment} disabled={appleBusy||!appleDeviceName.trim()}>{appleBusy?"Working…":"Create enrollment code"}</button></div>
     {appleEnrollment&&<div className="apple-enrollment-code"><div><b>One-time enrollment code</b><small>Expires {new Date(appleEnrollment.expires_at).toLocaleString()} · usable once</small></div><code>{appleEnrollment.enrollment_token}</code><button className="button secondary compact" onClick={copyAppleEnrollment}>Copy code</button><small>Keep this code private. Enter it in the Apple Shortcut enrollment step; the persistent device token is returned once and stored only in that Shortcut.</small></div>}
     {appleDevices.length===0?<p className="settings-muted">No Apple Shortcuts are enrolled. You can still queue commands; they will remain Pending on Device.</p>:appleDevices.map((device:any)=><div className="apple-device-row" key={device.id}><div><b>{device.name}</b><small>{device.is_active?"Active":"Revoked"} · Last seen {device.last_seen_at?new Date(device.last_seen_at).toLocaleString():"Never"}</small></div><span className="spacer"/>{device.is_active&&<button className="button secondary compact" onClick={()=>revokeAppleDevice(device.id)}>Revoke</button>}</div>)}
     <div className="section-head apple-command-heading"><h3>Apple action queue</h3><button className="button secondary compact" onClick={refresh}>Refresh</button></div>
     {appleCommands.length===0?<p className="settings-muted">No Notes or Reminders queued yet.</p>:appleCommands.slice(0,12).map((command:any)=><div className="apple-command-row" key={command.id}><div className="apple-command-icon">{command.command_type==="note"?<FileText size={16}/>:<CalendarClock size={16}/>}</div><div className="apple-command-info"><b>{command.payload?.title||"Apple action"}</b><small>{command.command_type==="note"?"Apple Note":"Apple Reminder"} · {new Date(command.created_at).toLocaleString()}</small>{command.status==="failed"&&<small className="apple-command-error">{command.error_message}</small>}{command.status==="completed"&&<small>Apple confirmed creation{command.result?.native_record_id?" · "+command.result.native_record_id:""}</small>}</div><span className={"apple-command-state "+command.status}>{command.status.replaceAll("_"," ")}</span><div className="apple-command-actions">{command.status==="failed"&&<button className="button secondary compact" onClick={()=>retryAppleCommand(command.id)}>Retry</button>}{command.status==="pending_on_device"&&<button className="button secondary compact" onClick={()=>cancelAppleCommand(command.id)}>Cancel</button>}</div></div>)}
     <p className="settings-muted">The app never claims a Note or Reminder exists until an authorised Shortcut reports success. Each command carries a unique marker so a retry can check for a previously created native item before creating another.</p>
     <a href="https://github.com/mehulmanu98-png/email-assistant/blob/main/docs/apple-shortcuts-setup.md" target="_blank" rel="noreferrer">Apple Shortcut setup guide <ExternalLink size={12}/></a>
    </div>
    <div className="settings-block"><h3>AI connection and privacy</h3><p><AlertCircle size={15}/> ChatGPT Go can be eligible for supported app integrations, but this app has not received commercial integration approval. The open-source DevKit licence is noncommercial and is not used for business operations. No paid API or credit fallback is enabled.</p><p><ShieldCheck size={15}/> Background AI processing is disabled until explicit consent and eligibility checks are completed.</p><div className="settings-links"><a href="https://openai.com/form/sign-in-with-chatgpt/" target="_blank" rel="noreferrer">Request commercial integration approval <ExternalLink size={12}/></a><a href="https://chatgpt.com/#settings/Usage" target="_blank" rel="noreferrer">Manage ChatGPT usage <ExternalLink size={12}/></a></div></div>
    <form className="settings-block" onSubmit={saveSchedule}><h3>Automatic mailbox synchronisation</h3><p><Clock size={15}/> These times sync email only. AI review and notifications remain disabled.</p><label>Times (24-hour, comma-separated)</label><input value={syncTimesText} onChange={e=>setSyncTimesText(e.target.value)} placeholder="08:00, 12:00, 17:00" required/><label>Timezone (IANA name)</label><input value={settingsData.timezone} onChange={e=>setSettingsData({...settingsData,timezone:e.target.value})} required/><button className="button secondary">Save schedule</button><small>Default: 08:00, 12:00 and 17:00 Asia/Kolkata.</small></form>
    <div className="settings-block"><h3>Current integration status</h3><p>iCloud and Gmail OAuth are wired. Read-state write-back, provider Trash, reply/forward approval, original attachment viewing/download and email-to-conversation linking are implemented. Apple Notes/Reminders commands can be queued and are completed only after an enrolled Shortcut confirms native creation. AI summaries, AI-generated replies and delegated AI execution remain blocked pending commercial integration approval.</p></div>
   </section>}
   <footer>Private single-user workspace · Asia/Kolkata · No proactive notifications</footer>
  </main>
  {showCompose&&<div className="modal-backdrop"><div className="modal compose-modal">
   <div className="section-head"><div><h2>New email</h2><p>Choose the sender account explicitly. This draft is stored in Email Assistant until you approve sending.</p></div><button type="button" className="icon-button" onClick={()=>setShowCompose(false)}><X size={17}/></button></div>
   {!outboundDraft&&savedOutboundDrafts.length>0&&<div className="saved-outbound-list"><b>Saved drafts</b>{savedOutboundDrafts.map((item:any)=><button type="button" className="saved-outbound-item" key={item.id} onClick={()=>resumeOutboundDraft(item)}><span><b>{item.subject||"(No subject)"}</b><small>From {item.from_account} · Updated {item.updated_at?new Date(item.updated_at).toLocaleString():""}</small></span><span>Resume</span></button>)}</div>}
   <label>From account <span className="required-note">Required · no default sender</span></label><select value={outboundFromId} onChange={e=>setOutboundFromId(e.target.value)}><option value="">Choose a sending account</option>{accounts.filter((a:any)=>a.status==="connected").map((a:any)=><option key={a.id} value={a.id}>{a.email} ({a.provider.toUpperCase()})</option>)}</select>
   <label>To</label><input value={outboundTo} onChange={e=>setOutboundTo(e.target.value)} placeholder="recipient@example.com" />
   <label>CC</label><input value={outboundCc} onChange={e=>setOutboundCc(e.target.value)} placeholder="Optional, comma-separated"/>
   <label>BCC</label><input value={outboundBcc} onChange={e=>setOutboundBcc(e.target.value)} placeholder="Optional, comma-separated"/>
   <label>Subject</label><input value={outboundSubject} onChange={e=>setOutboundSubject(e.target.value)} maxLength={998}/>
   <label>Message</label><textarea rows={9} value={outboundBody} onChange={e=>setOutboundBody(e.target.value)} maxLength={100000}/>
   <small>Reply and forward actions use their original receiving account. For a new email, the From account above is the one that will send it. Saving here does not create a draft in iCloud or Gmail.</small>
   <div className="inline-actions compose-actions"><button type="button" className="button secondary" onClick={()=>setShowCompose(false)}>Close</button><button type="button" className="button secondary" onClick={saveOutboundDraft} disabled={composeBusy||!outboundFromId}>{composeBusy?"Saving…":"Save Draft"}</button><button type="button" className="button primary" onClick={sendOutboundEmail} disabled={composeBusy||!outboundFromId}>{composeBusy?"Working…":"Review & Send"}</button></div>
  </div></div>}
  {showAccount&&<div className="modal-backdrop"><form className="modal" onSubmit={connect}><div className="section-head"><h2>Connect email account</h2><button type="button" className="icon-button" onClick={()=>setShowAccount(false)}><X size={17}/></button></div><label>Provider</label><select value={provider} onChange={e=>setProvider(e.target.value)}><option value="icloud">iCloud Mail</option><option value="gmail">Gmail · Continue with Google</option></select>{provider==="icloud"&&<><label>Email address</label><input type="email" value={newEmail} onChange={e=>setNewEmail(e.target.value)} required/><label>Apple app-specific password</label><input type="password" value={appPassword} onChange={e=>setAppPassword(e.target.value)} required/><small>Use an Apple app-specific password, not your main Apple Account password.</small></>} {provider==="gmail"&&<small>You will be redirected to Google to approve secure Gmail access. Never enter your Google password here.</small>}<button className="button primary full">{provider==="icloud"?"Save and sync iCloud":"Continue with Google"}</button></form></div>}
 </div>;
}
